import unittest


def eat(number, need, remaining):
    if(need <= remaining):
        return [ number + need , remaining-need ]
    else:
        return [ number + remaining , 0]


class TestEat(unittest.TestCase):

    def test_enough_remaining(self):
        self.assertEqual(eat(5, 6, 10), [11, 4])

    def test_exactly_enough(self):
        self.assertEqual(eat(2, 3, 3), [5, 0])

    def test_not_enough_remaining(self):
        self.assertEqual(eat(4, 8, 5), [9, 0])

    def test_no_need(self):
        self.assertEqual(eat(10, 0, 5), [10, 5])

    def test_no_remaining(self):
        self.assertEqual(eat(7, 4, 0), [7, 0])

    def test_zero_values(self):
        self.assertEqual(eat(0, 0, 0), [0, 0])

    def test_large_numbers(self):
        self.assertEqual(eat(1000, 500, 2000), [1500, 1500])

    def test_need_exceeds_remaining(self):
        self.assertEqual(eat(1, 10, 3), [4, 0])

    def test_eat_one(self):
        self.assertEqual(eat(0, 1, 1), [1, 0])

    def test_result_types(self):
        result = eat(5, 3, 10)
        self.assertIsInstance(result, list)
        self.assertEqual(len(result), 2)
        self.assertTrue(all(isinstance(x, int) for x in result))


if __name__ == "__main__":
    unittest.main()
